B.bfE=new A.V("1. SOBRE A PLATAFORMA",null,B.e8,null,null,null,null,null,null,null,null,null,null)
B.eG=new A.z(!0,B.Z,null,null,null,null,12.5,null,null,null,null,null,1.4,null,null,null,null,null,null,null,null,null,null,null,null,null)
B.beR=new A.V("O M\xe3o na Roda, operado pela Impetus Tecnologia, \xe9 uma plataforma de intermedia\xe7\xe3o e conveni\xeancia que conecta clientes tomadores de servi\xe7os a profissionais prestadores parceiros aut\xf4nomos.",null,B.eG,null,null,null,null,null,null,null,null,null,null)
B.bbO=new A.V("2. CUST\xd3DIA FINANCEIRA SEGURA (ESCROW)",null,B.e8,null,null,null,null,null,null,null,null,null,null)
B.bfa=new A.V("Todo valor pago (via PIX ou Cart\xe3o de Cr\xe9dito) \xe9 mantido em cust\xf3dia protegida pela plataforma. O valor s\xf3 \xe9 transferido para a carteira do prestador ap\xf3s a confirma\xe7\xe3o e aprova\xe7\xe3o expressa do servi\xe7o pelo cliente.",null,B.eG,null,null,null,null,null,null,null,null,null,null)
B.bdp=new A.V("3. TAXA DE SERVI\xc7O & REPASSE",null,B.e8,null,null,null,null,null,null,null,null,null,null)
B.bee=new A.V("A plataforma ret\xe9m uma taxa de intermedia\xe7\xe3o e seguran\xe7a de 10% sobre o valor total do chamado, repassando 90% l\xedquido ao prestador do atendimento.",null,B.eG,null,null,null,null,null,null,null,null,null,null)
B.bcK=new A.V("4. PRAZOS E PONTUALIDADE",null,B.e8,null,null,null,null,null,null,null,null,null,null)
B.bdO=new A.V("O prestador deve cumprir os prazos de deslocamento:\n\u2022 At\xe9 1 km de dist\xe2ncia: chegada em at\xe9 30 minutos.\n\u2022 Acima de 1 km: chegada em at\xe9 1 hora.\nO n\xe3o comparecimento sem justificativa enseja penalidades e cancelamento do chamado.",null,B.eG,null,null,null,null,null,null,null,null,null,null)
B.Xj=new A.z(!0,B.H,null,null,null,null,13,B.u,null,null,null,null,null,null,null,null,null,null,null,null,null,null,null,null,null,null)
B.bc6=new A.V("5. CANAL SEGURO & PROIBI\xc7\xc3O DE INTERMEDIA\xc7\xc3O EXTERNA",null,B.Xj,null,null,null,null,null,null,null,null,null,null)
B.bfj=new A.V("\xc9 estritamente proibido trocar contatos externos (n\xfameros de telefone, WhatsApp particular, chaves PIX externas ou redes sociais) pelo chat do aplicativo com o objetivo de negociar fora da plataforma. A infra\xe7\xe3o acarreta o bloqueio imediato e banimento definitivo das contas envolvidas.",null,B.eG,null,null,null,null,null,null,null,null,null,null)
B.bct=new A.V("6. AVALIA\xc7\xd5ES E CONDUTA",null,B.e8,null,null,null,null,null,null,null,null,null,null)
B.bfo=new A.V("Todas as partes concordam em agir com respeito m\xfatuo, integridade e profissionalismo. Ao fim de cada atendimento, o cliente realiza a avalia\xe7\xe3o de 1 a 5 estrelas que comp\xf5e a pontua\xe7\xe3o p\xfablica do profissional.",null,B.eG,null,null,null,null,null,null,null,null,null,null)
